def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"
    ERRORS = {DIV0, CYCLE}

    token_re = re.compile(
        r"\s*(<=|>=|<>|[()+\-*/,:=<>]|[A-Za-z]+|\d+)"
    )

    class Parser:
        def __init__(self, text):
            self.tokens = [m.group(1) for m in token_re.finditer(text)]
            self.i = 0

        def peek(self):
            return self.tokens[self.i] if self.i < len(self.tokens) else None

        def take(self, expected=None):
            token = self.peek()
            if token is None or (expected is not None and token != expected):
                raise ValueError("Invalid formula")
            self.i += 1
            return token

        def expression(self):
            node = self.term()
            while self.peek() in ("+", "-"):
                op = self.take()
                node = (op, node, self.term())
            return node

        def term(self):
            node = self.unary()
            while self.peek() in ("*", "/"):
                op = self.take()
                node = (op, node, self.unary())
            return node

        def unary(self):
            if self.peek() == "-":
                self.take()
                return ("neg", self.unary())
            return self.atom()

        def atom(self):
            token = self.peek()
            if token == "(":
                self.take("(")
                node = self.expression()
                self.take(")")
                return node
            if token is not None and token.isdigit():
                self.take()
                return ("num", int(token))
            if token is not None and token[0].isalpha():
                name = self.take().upper()
                if self.peek() == "(":
                    self.take("(")
                    if name == "IF":
                        left = self.expression()
                        op = self.take()
                        right = self.expression()
                        self.take(",")
                        then = self.expression()
                        self.take(",")
                        otherwise = self.expression()
                        self.take(")")
                        return ("if", left, op, right, then, otherwise)
                    args = []
                    while True:
                        # A range is recognized by a cell name followed by ':'.
                        if (
                            self.peek() is not None
                            and re.fullmatch(r"[A-Za-z]+[1-9]\d*", self.peek())
                            and self.i + 1 < len(self.tokens)
                            and self.tokens[self.i + 1] == ":"
                        ):
                            start = self.take().upper()
                            self.take(":")
                            end = self.take().upper()
                            args.append(("range", start, end))
                        else:
                            args.append(self.expression())
                        if self.peek() != ",":
                            break
                        self.take(",")
                    self.take(")")
                    return ("func", name, args)
                return ("ref", name)
            raise ValueError("Invalid formula")

    def cell_pos(name):
        m = re.fullmatch(r"([A-Z])([1-9]\d?)", name.upper())
        return ord(m.group(1)) - ord("A"), int(m.group(2))

    parsed = {}
    for name, content in cells.items():
        if content.startswith("="):
            parsed[name] = Parser(content[1:]).expression()
        else:
            parsed[name] = ("num", int(content))

    values = {}
    active = set()

    def evaluate_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return CYCLE
        active.add(name)
        result = evaluate(parsed[name])
        active.remove(name)
        values[name] = result
        return result

    def evaluate(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return evaluate_cell(node[1])
        if kind == "neg":
            value = evaluate(node[1])
            return value if value in ERRORS else -value
        if kind in ("+", "-", "*", "/"):
            left = evaluate(node[1])
            if left in ERRORS:
                return left
            right = evaluate(node[2])
            if right in ERRORS:
                return right
            if kind == "+":
                return left + right
            if kind == "-":
                return left - right
            if kind == "*":
                return left * right
            if right == 0:
                return DIV0
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "if":
            left = evaluate(node[1])
            if left in ERRORS:
                return left
            right = evaluate(node[3])
            if right in ERRORS:
                return right
            op = node[2]
            condition = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }[op]
            return evaluate(node[4] if condition else node[5])
        if kind == "range":
            return node
        if kind == "func":
            name, args = node[1], node[2]
            collected = []
            for arg in args:
                if arg[0] == "range":
                    c1, r1 = cell_pos(arg[1])
                    c2, r2 = cell_pos(arg[2])
                    for row in range(min(r1, r2), max(r1, r2) + 1):
                        for col in range(min(c1, c2), max(c1, c2) + 1):
                            cell_name = chr(ord("A") + col) + str(row)
                            if cell_name in cells:
                                value = evaluate_cell(cell_name)
                                if value in ERRORS:
                                    return value
                                collected.append(value)
                else:
                    value = evaluate(arg)
                    if value in ERRORS:
                        return value
                    collected.append(value)
            if not collected:
                return 0
            if name == "SUM":
                return sum(collected)
            if name == "MIN":
                return min(collected)
            if name == "MAX":
                return max(collected)
            raise ValueError("Invalid function")
        raise ValueError("Invalid node")

    return {name: evaluate_cell(name) for name in cells}
